{
    Show(GetData());   // GetData ждёт ответ сервера: поток стоит
}                      // следующий клик возьмут только после выхода

cards/3/code:
// синхронно: поток стоит в GetData, клики копятся
void OnClick()       { Show(GetData()); }

// асинхронно: пока идёт запрос, поток свободен
async void OnClick() { var r = await GetDataAsync(); Show(r); }

cards/4/code:
async void OnClick()
{
    var r = await GetDataAsync(); // 1–2. запрос ушёл, обработчик вернул управление
                                  // 3. главный поток разбирает другие события
    Show(r);                      // 4–5. продолжение: из очереди, снова на главном потоке
}
